#include "flight/StrategicFlightSystem.h"
#include <algorithm>
namespace subspace {
void StrategicFlightSystem::ToggleMode(){mode_=mode_==FlightControlMode::Manual?FlightControlMode::Strategic:FlightControlMode::Manual;}
StrategicFlightIntent StrategicFlightSystem::Evaluate(const Vector3& ship,const Vector3& target,float distance) const {StrategicFlightIntent i;if(mode_!=FlightControlMode::Strategic||!order_.valid)return i;Vector3 d=target-ship;if(d.length()>.001f)i.desiredDirection=d.normalized();switch(order_.kind){case StrategicOrderKind::Approach:i.desiredThrottle=distance>std::max(10.0f,order_.desiredRange)?1.0f:.15f;break;case StrategicOrderKind::Orbit:i.desiredThrottle=.55f;break;case StrategicOrderKind::KeepRange:i.desiredThrottle=distance>order_.desiredRange*1.05f?.65f:distance<order_.desiredRange*.95f?-.45f:0.0f;break;case StrategicOrderKind::Align:i.desiredThrottle=.25f;break;case StrategicOrderKind::Follow:i.desiredThrottle=.65f;break;case StrategicOrderKind::Hold:i.desiredThrottle=0;break;case StrategicOrderKind::Engage:i.desiredThrottle=.48f;i.fire=true;break;case StrategicOrderKind::Mine:i.desiredThrottle=.25f;i.fire=true;break;case StrategicOrderKind::Salvage:i.desiredThrottle=.22f;break;case StrategicOrderKind::Dock:i.desiredThrottle=.18f;i.requestDock=true;break;case StrategicOrderKind::VectorTo:i.useVector=true;i.desiredThrottle=1.0f;break;default:break;}return i;}
} // namespace subspace
